package com.procurement.approvalstage.controller;import com.procurement.approvalstage.dto.request.*;import com.procurement.approvalstage.dto.response.*;import com.procurement.approvalstage.service.*;import com.procurement.common.response.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/approval-stages")public class ApprovalStageController{private final ApprovalStageService service;public ApprovalStageController(ApprovalStageService s){service=s;}private Pageable p(int page,int size,String sort,String direction){return PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort));}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','PROCUREMENT_MANAGER','PROCUREMENT_OFFICER')")public ResponseEntity<ApiResponse<ApprovalStageResponse>>create(@Valid@RequestBody ApprovalStageRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Approval stage created",service.create(r)));}@GetMapping public ApiResponse<PageResponse<ApprovalStageResponse>>search(@RequestParam(required=false)Long approvalRuleId,@RequestParam(required=false)Long approverRoleId,@RequestParam(required=false)Boolean active,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="sequence")String sort,@RequestParam(defaultValue="asc")String direction){return ApiResponse.success(service.search(approvalRuleId,approverRoleId,active,p(page,size,sort,direction)));}@GetMapping("/{id}")public ApiResponse<ApprovalStageResponse>get(@PathVariable Long id){return ApiResponse.success(service.getById(id));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','PROCUREMENT_MANAGER','PROCUREMENT_OFFICER')")public ApiResponse<ApprovalStageResponse>update(@PathVariable Long id,@Valid@RequestBody ApprovalStageRequest r){return ApiResponse.success("Approval stage updated",service.update(id,r));}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','PROCUREMENT_MANAGER','PROCUREMENT_OFFICER')")public ResponseEntity<Void>delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
